/*
  Consolidated customer script (cart + UI helpers)
  - Uses `window.cartState` (provided by /js/cart-state.js) when available
  - Provides `addToCart`, `updetecart` and checkout bindings (CSP-safe)
  - Keeps existing DOM classes/IDs so styling is preserved
*/
(function () {
  'use strict';

  // Utility
  const $ = (sel, ctx = document) => ctx.querySelector(sel);
  const $$ = (sel, ctx = document) => Array.from(ctx.querySelectorAll(sel));

  // --- Storage helpers (fallback) ---
  function lsGetCart() {
    try { return JSON.parse(localStorage.getItem('cart')) || []; } catch { return []; }
  }
  function lsSetCart(items) {
    try { localStorage.setItem('cart', JSON.stringify(items || [])); } catch {}
  }

  function getItems() {
    if (window.cartState && typeof window.cartState.getItems === 'function') {
      try { return window.cartState.getItems() || []; } catch { return []; }
    }
    return lsGetCart();
  }

  function clearCart() {
    if (window.cartState && typeof window.cartState.clear === 'function') {
      try { window.cartState.clear(); return; } catch {}
    }
    try { localStorage.removeItem('cart'); } catch {}
  }

  // --- Public API: addToCart ---
  function addToCart(product) {
    const item = {
      id: product.id || product.Product_ID,
      title: product.title || product.Product_Name,
      price: Number(product.price || product.Price) || 0,
      img: product.img || `images/products/${product.Image}`,
      quantity: 1
    };

    if (window.cartState && typeof window.cartState.addItem === 'function') {
      try { window.cartState.addItem(item); } catch {}
    } else {
      const s = lsGetCart();
      // لو عايز تمنع التكرار وتزوّد الكمية بدل ما تضيف نفس المنتج:
      const idx = s.findIndex(x => String(x.id) === String(item.id));
      if (idx > -1) s[idx].quantity = (Number(s[idx].quantity) || 1) + 1;
      else s.push(item);
      lsSetCart(s);
    }

    updetecart();

    const cartEl = $('.cart');
    if (cartEl) cartEl.classList.add('active');
  }

  // --- UI helpers ---
  function showCartMessage(message, type = 'info') {
    const el = document.getElementById('cart_message');
    if (!el) return;

    el.textContent = message;
    el.className = 'cart_message ' + type;
    el.style.display = 'block';

    const colors = {
      success: '#4CAF50',
      error: 'var(--text-color)',
      warning: '#ff9800',
      info: '#2196F3'
    };
    el.style.backgroundColor = colors[type] || colors.info;
    el.style.color = '#fff';

    if (type !== 'error') {
      setTimeout(() => { el.style.display = 'none'; }, 4000);
    }
  }

  function updetButtoncart(productId) {
    $$('.button-data-id[data-id="' + productId + '"]').forEach(b => {
      b.classList.remove('activess');
      b.disabled = false;
    });
  }

  // --- Render cart ---
  function updetecart() {
    const container = document.getElementById('cart_items');
    if (!container) return;

    const items = getItems();

    container.innerHTML = '';
    let total = 0;
    let qtyTotal = 0;

    items.forEach(it => {
      const q = Number(it.quantity) || 0;
      const p = Number(it.price) || 0;

      total += q * p;
      qtyTotal += q;

      const el = document.createElement('div');
      el.className = 'item_cart';
      el.innerHTML = `
        <img src="/${it.img}" alt="${it.title}">
        <div class="content">
          <h4>${it.title}</h4>
          <p class="price_cart">${(p * q).toFixed(2)} جنيه</p>
          <div class="quantity_control">
            <button class="decrese_quantity" data-id="${it.id}">-</button>
            <span class="quantity">${q}</span>
            <button class="increse_quantity" data-id="${it.id}">+</button>
          </div>
        </div>
        <button class="delete_item" data-id="${it.id}">
          <i class="ri-delete-bin-5-line"></i>
        </button>
      `;
      container.appendChild(el);
    });

    const priceEl = $('.price_cart_total');
    if (priceEl) priceEl.textContent = `${total.toFixed(2)} جنيه`;

    const countEl = $('.count_item_cart');
    if (countEl) countEl.textContent = `${qtyTotal}`;
  }

  // --- Quantity / delete actions (fallback) ---
  function increaseLocal(id) {
    const s = lsGetCart();
    const idx = s.findIndex(x => String(x.id) === String(id));
    if (idx > -1) {
      s[idx].quantity = (Number(s[idx].quantity) || 0) + 1;
      lsSetCart(s);
      updetecart();
    }
  }

  function decreaseLocal(id) {
    const s = lsGetCart();
    const idx = s.findIndex(x => String(x.id) === String(id));
    if (idx > -1) {
      s[idx].quantity = Math.max(1, (Number(s[idx].quantity) || 1) - 1);
      lsSetCart(s);
      updetecart();
    }
  }

  function removeLocal(id) {
    const s = lsGetCart();
    const idx = s.findIndex(x => String(x.id) === String(id));
    if (idx > -1) {
      const removed = s.splice(idx, 1)[0];
      lsSetCart(s);
      updetecart();
      if (removed && removed.id != null) updetButtoncart(removed.id);
    }
  }

  // --- Checkout ---
  function getSubtotal(items) {
    return (items || []).reduce((sum, i) => sum + (Number(i.price) || 0) * (Number(i.quantity) || 0), 0);
  }

  function handleCheckout() {
    const items = getItems();

    if (!items || items.length === 0) {
      showCartMessage('السلة فارغة! الرجاء إضافة منتجات.', 'warning');
      return;
    }

    if (typeof window.isAuthenticated !== 'function' || !window.isAuthenticated()) {
      showCartMessage('يجب تسجيل الدخول أولاً لإتمام الطلب!', 'error');
      try {
        localStorage.setItem('pendingCart', JSON.stringify(items));
        localStorage.setItem('postAuthRedirect', window.location.pathname + window.location.search);
        localStorage.setItem('checkoutIntent', 'true');
      } catch {}

      setTimeout(() => {
        if (typeof window.redirectToLogin === 'function') window.redirectToLogin();
        else window.location.href = '/register';
      }, 800);
      return;
    }

    const subtotal =
      (window.cartState && typeof window.cartState.getTotals === 'function')
        ? (window.cartState.getTotals()?.subtotal ?? getSubtotal(items))
        : getSubtotal(items);

    if (typeof window.openCheckoutModal === 'function') {
      window.openCheckoutModal(items, subtotal);
      return;
    }

    showCartMessage(`جاري معالجة الطلب بقيمة ${subtotal.toFixed(2)} جنيه...`, 'info');
    submitOrder(items, subtotal);
  }

  async function submitOrder(items, totalAmount) {
    try {
      const res = await fetch('/api/orders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          items: items.map(i => ({
            productId: i.id,
            quantity: i.quantity,
            price: i.price
          })),
          totalAmount,
          deliveryAddress: 'عنوان التوصيل'
        })
      });

      const data = await res.json().catch(() => ({}));

      if (res.status === 401) {
        showCartMessage('يجب عليك تسجيل الدخول أولاً!', 'error');
        try {
          localStorage.setItem('pendingCart', JSON.stringify(items));
          localStorage.setItem('postAuthRedirect', window.location.pathname + window.location.search);
          localStorage.setItem('checkoutIntent', 'true');
        } catch {}
        setTimeout(() => {
          if (typeof window.redirectToLogin === 'function') window.redirectToLogin();
          else window.location.href = '/register';
        }, 800);
        return;
      }

      if (!data.success) {
        const errorMessage = data.message || data.error?.message || 'فشل في إنشاء الطلب';
        showCartMessage(`✗ خطأ: ${errorMessage}`, 'error');
        return;
      }

      showCartMessage(`✓ تم إنشاء الطلب بنجاح! رقم الطلب: ${data.data?.orderNumber || ''}`, 'success');

      clearCart();
      updetecart();

      // لو عندك close للسلة
      try {
        if (window.cartState && typeof window.cartState.close === 'function') window.cartState.close();
      } catch {}
    } catch (err) {
      showCartMessage('✗ خطأ في الاتصال', 'error');
    }
  }

  // --- Bindings (delegation) ---
  function bindDelegatedClicks() {
    document.addEventListener('click', function (e) {
      const inc = e.target.closest && e.target.closest('.increse_quantity');
      if (inc) {
        const id = inc.dataset.id;
        if (window.cartState && typeof window.cartState.increaseQuantity === 'function') {
          window.cartState.increaseQuantity(Number(id) || id);
        } else {
          increaseLocal(id);
        }
        return;
      }

      const dec = e.target.closest && e.target.closest('.decrese_quantity');
      if (dec) {
        const id = dec.dataset.id;
        if (window.cartState && typeof window.cartState.decreaseQuantity === 'function') {
          window.cartState.decreaseQuantity(Number(id) || id);
        } else {
          decreaseLocal(id);
        }
        return;
      }

      const del = e.target.closest && e.target.closest('.delete_item');
      if (del) {
        const id = del.dataset.id;
        if (window.cartState && typeof window.cartState.removeItem === 'function') {
          window.cartState.removeItem(Number(id) || id);
        } else {
          removeLocal(id);
        }
        return;
      }

      const checkoutBtn = e.target.closest && e.target.closest('.btn_cart');
      if (checkoutBtn) {
        e.preventDefault();
        handleCheckout();
      }
    });
  }

  // Init
  function init() {
    bindDelegatedClicks();
    updetecart();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Expose for templates
  window.addToCart = addToCart;
  window.updetecart = updetecart;

})();